        self.smtp = SmtpClient()
        self.pdf_gen = PdfGenerator()
        self.audit_logger = AuditLogger()  # four unrelated collaborators - a red flag on its own

    def calculate_total(self, order):
        return order.amount * order.quantity

    def apply_discount(self, total, qty):
        return total * 0.9 if qty >= 10 else total

    def save_to_database(self, order):
        self.db.execute(f"INSERT order {order.order_id}")

    def send_confirmation(self, email):
        self.smtp.send(email, "Your order is confirmed")

    def generate_invoice_pdf(self, order):
        return self.pdf_gen.render(order)

    def log_audit_trail(self, order):
        self.audit_logger.record(order)


