        std::cout << "EMAIL to " << email << ": " << message << std::endl;
    }
};

class PdfGenerator {
public:
    std::vector<char> render(const Order& order) {
        std::cout << "PDF: generated invoice for order " << order.getId() << std::endl;
        return {};
    }
};

class AuditLogger {
public:
    void record(const Order& order) {
        std::cout << "AUDIT: order " << order.getId() << " recorded" << std::endl;
    }
};

