    void sendConfirmation(const std::string& email) { smtp.send(email, "Your order is confirmed"); }
    std::vector<char> generateInvoicePdf(const Order& order) { return pdfGen.render(order); }
    void logAuditTrail(const Order& order) { auditLogger.record(order); }

private:
    Connection db;
    SmtpClient smtp;
    PdfGenerator pdfGen;
    AuditLogger auditLogger;   // four unrelated collaborators - a red flag on its own
};

int main() {
    Order order("ORD-1", "ana@example.com", 50.0, 12);
    OrderService service;

    double total = service.calculateTotal(order);
    total = service.applyDiscount(total, order.getQuantity());
    service.saveToDatabase(order);
    service.sendConfirmation(order.getEmail());
    service.generateInvoicePdf(order);
    service.logAuditTrail(order);

    std::cout << "Total after discount: " << total << std::endl;
    return 0;
}

